CREATE TABLE IF NOT EXISTS invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), project_id UUID REFERENCES projects(id), invoice_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft', issue_date DATE NOT NULL, due_date DATE NOT NULL, subtotal NUMERIC(12,2) NOT NULL DEFAULT 0, tax_total NUMERIC(12,2) NOT NULL DEFAULT 0, total NUMERIC(12,2) NOT NULL DEFAULT 0, amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0, outstanding_balance NUMERIC(12,2) NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'GBP', notes TEXT, created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoice_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity NUMERIC(12,2) NOT NULL DEFAULT 1, unit_price NUMERIC(12,2) NOT NULL DEFAULT 0, tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0, line_total NUMERIC(12,2) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, company_id UUID NOT NULL REFERENCES companies(id), amount NUMERIC(12,2) NOT NULL, payment_date DATE NOT NULL, payment_method TEXT, reference TEXT, external_payment_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
